      "title": "稀缺与选择：机会成本",
      "summary": "稀缺让每个选择都附带放弃，机会成本是这笔放弃的完整价格，而人常常看不见它。",
      "type": "Learn",
      "prereq": "00-01、00-02",
      "minutes": "45–60 分钟",
      "url": "lessons/01-economics-basics/01-scarcity-choice/"
