      "slug": "02-marginal-thinking",
      "title": "边际思维：多一个单位的取舍",
      "summary": "决策看的是再多一个单位的边际量，而不是总量；已经花掉、收不回的沉没成本不该进决策。",
      "type": "Learn",
      "prereq": "01-01",
      "minutes": "45–60 分钟",
      "url": "lessons/01-economics-basics/02-marginal-thinking/"
