      "num": "05",
      "slug": "05-elasticity",
      "title": "弹性：数量对价格有多敏感",
      "summary": "弹性衡量数量对价格有多敏感，它决定了税收、涨价与限价的后果最终落在消费者、生产者还是政府身上。",
      "type": "Learn",
      "prereq": "01-03、01-04",
      "minutes": "45–60 分钟",
      "url": "lessons/01-economics-basics/05-elasticity/"
