      "title": "策略互动：从囚徒困境到纳什均衡",
      "summary": "当结果取决于他人的选择，个体理性可能把所有人推向次优；重复互动与惩罚能扭转它。",
      "type": "Learn",
      "prereq": "01-04、01-06",
      "minutes": "45–60 分钟",
      "url": "lessons/01-economics-basics/07-strategic-interaction/"
