      "title": "风险与期望效用",
      "summary": "期望效用是风险决策的基准，而人对概率与得失的处理系统性地偏离它。",
      "type": "Learn",
      "prereq": "01-02",
      "minutes": "45–60 分钟",
      "url": "lessons/01-economics-basics/08-risk-expected-utility/"
