      "num": "01",
      "slug": "01-perception-attention",
      "title": "知觉与注意：信息如何进入心智",
      "summary": "人并非被动接收世界的全部信息，知觉与注意先做了筛选，所以「看到什么」本身就是一个有待解释的问题。",
      "type": "Learn",
      "prereq": "00-01、00-02",
      "minutes": "45–60 分钟",
      "url": "lessons/02-psychology-basics/01-perception-attention/"
