      "slug": "02-memory-reconstruction",
      "title": "记忆：不是回放，而是重建",
      "summary": "记忆不是对过去的忠实录像，而是每次提取时依据线索与知识重新拼合，因此可被事后信息悄然改写。",
      "type": "Learn",
      "prereq": "02-01",
      "minutes": "45–60 分钟",
      "url": "lessons/02-psychology-basics/02-memory-reconstruction/"
