      "module": "02",
      "moduleDir": "02-psychology-basics",
      "num": "05",
      "slug": "05-emotion-appraisal",
      "title": "情绪与评价：感受如何参与判断",
      "summary": "情绪不是理性的对立面，而是评价系统的输出；它以好恶快速标价，并持续参与判断。",
      "type": "Learn",
      "prereq": "02-04",
      "minutes": "45–60 分钟",
      "url": "lessons/02-psychology-basics/05-emotion-appraisal/"
