      "id": "02-06",
      "module": "02",
      "moduleDir": "02-psychology-basics",
      "num": "06",
      "slug": "06-motivation",
      "title": "动机：为什么做，以及为什么不做",
      "summary": "人做事的动力来自内外两套来源，而外部奖励有时会破坏本已存在的内在动机。",
      "type": "Learn",
      "prereq": "02-03、02-05",
      "minutes": "45–60 分钟",
      "url": "lessons/02-psychology-basics/06-motivation/"
