      "title": "社会认知：我们如何理解他人",
      "summary": "理解他人时我们总在推断原因，而这些推断系统性地偏向把行为归于性格、忽略情境。",
      "type": "Learn",
      "prereq": "02-04",
      "minutes": "45–60 分钟",
      "url": "lessons/02-psychology-basics/07-social-cognition/"
