      "title": "态度与说服：观点如何形成与改变",
      "summary": "态度会随情境与行为改变，而最有效的说服取决于人是否有动机与能力去认真思考。",
      "type": "Learn",
      "prereq": "02-07",
      "minutes": "45–60 分钟",
      "url": "lessons/02-psychology-basics/08-attitudes-persuasion/"
