      "summary": "人在行为上确实存在稳定的个体差异，但情境的力量常被低估，二者共同决定一个人的行为。",
      "type": "Learn",
      "prereq": "02-04、02-08",
      "minutes": "45–60 分钟",
      "url": "lessons/02-psychology-basics/09-personality-differences/"
