      "summary": "心理属性无法直接观测，只能靠测量间接推断；因此「测得准不准」决定了心理学结论能不能当证据用。",
      "type": "Learn",
      "prereq": "02-09",
      "minutes": "45–60 分钟",
      "url": "lessons/02-psychology-basics/10-measurement-reliability/"
