      "summary": "理性人假设是分析市场的有力基准，但它描述的是\"应该怎样选\"，而非\"实际怎样选\"；二者的裂缝正是行为经济学的入口。",
      "type": "Learn",
      "prereq": "01-08、00-02",
      "minutes": "45–60 分钟",
      "url": "lessons/03-behavioral-core/01-from-eu-to-behavioral/"
