      "num": "02",
      "slug": "02-loss-aversion",
      "title": "损失厌恶：失去的痛重于得到的爽",
      "summary": "同样一笔钱，失去带来的痛明显大于得到带来的爽；这种心理不对称，如何改写风险下的选择与公平直觉。",
      "type": "Learn",
      "prereq": "03-01",
      "minutes": "45–60 分钟",
      "url": "lessons/03-behavioral-core/02-loss-aversion/"
