      "title": "框架效应：表述方式如何反转选择",
      "summary": "同一个客观事实，用\"救活多少人\"还是\"死多少人\"来表述，人们的选择会整个反转——理性人假设在这里裂开了一道缝。",
      "type": "Learn",
      "prereq": "03-03",
      "minutes": "45–60 分钟",
      "url": "lessons/03-behavioral-core/09-framing-effect/"
