          "correct": 1,
          "explanation": "几十年后兑现、几乎没有反馈，意味着学习机会极少；复杂产品通常竞争不充分、套利工具缺失，四项判据几乎全低，所以偏差会留存。「参与者会自学成才」低估了反馈的必要性：在没有及时反馈的领域，重复经验不会自动变成最优选择。选「无法判断」则放弃了本讲提供的推理工具。"
