          "correct": 1,
          "explanation": "机会成本是「被放弃的最有价值的替代方案」，所以正确项指向那四小时本来最有价值的用途——可能是避免挂科。最容易误选「零成本」：你确实没花钱，但把「成本＝付出的钱」当成了定义，漏掉了被放弃的复习；「80 元收入」则正好记反了方向，把收益当成了成本。"
